with flattened_attrs as (select id, customer_id, created_at, coupon_codes, items, array_max(transform(items, x -> x.price)) as max_item_price, coalesce(attributes['device'], 'none') as device_or_default from carts) select id, customer_id, created_at, max_item_price, max(max_item_price) over w_grp as running_max_max_item_price, min(max_item_price) over w_grp as running_min_max_item_price, count(max_item_price) over w_grp as running_count_max_item_price, avg(max_item_price) over w_grp as running_avg_max_item_price, row_number() over (partition by customer_id order by max_item_price, id) as event_seq from flattened_attrs window w_grp as (partition by customer_id order by created_at, id rows between unbounded preceding and current row);
